impl Solution{pub fn num_islands2(m:i32,n:i32,pos:Vec<Vec<i32>>)->Vec<i32>{fn f(p:&mut Vec<i32>,x:usize)->usize{if p[x]as usize!=x{let r=f(p,p[x]as usize);p[x]=r as i32;}p[x]as usize}let(mut p,mut o,mut c)=(vec![-1;(m*n)as usize],vec![],0);let d=[(1,0),(-1,0),(0,1),(0,-1)];for v in pos{let(r,q)=(v[0],v[1]);let id=(r*n+q)as usize;if p[id]!=-1{o.push(c);continue}p[id]=id as i32;c+=1;for &(a,b) in &d{let(x,y)=(r+a,q+b);if x<0||y<0||x>=m||y>=n{continue}let j=(x*n+y)as usize;if p[j]==-1{continue}let u=f(&mut p,id);let v=f(&mut p,j);if u!=v{p[u]=v as i32;c-=1;}}o.push(c);}o}}
